  $foods[] = ['name'=>$f['food_name'],'en'=>$f['food_name'],'category'=>$f['category'],'qty'=>rtrim(rtrim((string)$f['quantity_kg'],'0'),'.').' কেজি','area'=>$f['pickup_address'] ?: $f['donor_address'],'expiry'=>date('d M, g:i A',strtotime($f['safety_deadline'])),'image'=>food_image_url($f),'status'=>'Available','live'=>true,'id'=>(int)$f['id']];
}
foreach ($demoFoods as $f) { if (count($foods)>=10) break; $foods[]=$f+['live'=>false]; }
// Homepage impact figures are read from the live database only; unavailable tables safely show zero.
$impact = ['donations'=>0, 'delivered'=>0, 'meals'=>0, 'community'=>0];
try { $impact['donations'] = (int)$pdo->query("SELECT COUNT(*) FROM surplus_food WHERE status NOT IN ('cancelled','rejected')")->fetchColumn(); } catch (Throwable $e) {}
try { $impact['delivered'] = (int)$pdo->query("SELECT COUNT(DISTINCT donation_request_id) FROM deliveries WHERE status IN ('delivered','completed')")->fetchColumn(); } catch (Throwable $e) {}
try { $impact['meals'] = (int)$pdo->query("SELECT COALESCE(SUM(meals_distributed),0) FROM distributions")->fetchColumn(); } catch (Throwable $e) {}
try { $impact['community'] = (int)$pdo->query("SELECT COUNT(*) FROM users WHERE is_active=1 AND role IN ('restaurant','ngo','volunteer')")->fetchColumn(); } catch (Throwable $e) {}
?>
